// Skyweave: native Photon sun-space distortion, with coarse DH material classes and no native atlas or voxel writes.
#include "/include/global.glsl"
#include "/include/lighting/shadows/distortion.glsl"
out vec2 uv;
flat out uint material_mask;
flat out vec3 tint;
flat out float skyweave_dh_alpha;
#ifdef WATER_CAUSTICS
out vec3 scene_pos;
#endif
uniform mat4 shadowModelViewInverse;
uniform vec3 cameraPosition;
void main() {
    uv = vec2(0.0);
    material_mask = dhMaterialId == DH_BLOCK_WATER ? 1u : 0u;
    tint = gl_Color.rgb;
    skyweave_dh_alpha = gl_Color.a;
    vec3 camera_offset = fract(cameraPosition);
    vec3 vertex = floor(gl_Vertex.xyz + camera_offset + 0.5) - camera_offset;
    vec3 pos = transform(gl_ModelViewMatrix, vertex);
#ifdef WATER_CAUSTICS
    scene_pos = transform(shadowModelViewInverse, pos);
#endif
    gl_Position = vec4(distort_shadow_space(project_ortho(gl_ProjectionMatrix, pos)), 1.0);
#ifdef WORLD_NETHER
    gl_Position = vec4(-1.0);
#endif
}

flat in vec3 tint;
#ifdef SKYWEAVE_DH_SHADOW
flat in float skyweave_dh_alpha;
#endif

#ifdef SKYWEAVE_DH_SHADOW
vec4 base_color = vec4(1.0, 1.0, 1.0, skyweave_dh_alpha);
#else
vec4 base_color = textureLod(tex, uv, 0);
#endif

